// NowId.ts
// -----------------------------------------------------------------------------
// Type utilities for adding a mandatory `$id` context parameter to transform
// functions, while preserving their original generics and return types.
// -----------------------------------------------------------------------------

/**
 * Prepends a `$id` context parameter to an existing function type
 * while preserving all original arguments and return type.
 *
 * @typeParam F - The original function type to wrap.
 *
 * @example
 * ```ts
 * type Original = (a: number, b: number) => string;
 * type WithId = WithNowId<Original>;
 * // Result:
 * // (context: Now.Internal.WithID<{ annotation?: string }>, a: number, b: number) => string
 * ```
 */
export type WithNowId<F extends (...args: any[]) => any> = F extends (...args: infer P) => infer R
    ? (context: Now.Internal.WithID<{ annotation?: string }>, ...args: P) => R
    : never

/**
 * For each property in type `T`:
 * - If the property is a function, prepend a `$id` context parameter.
 * - If it's not a function, leave it unchanged.
 *
 * @example
 * ```ts
 * interface MathFns {
 *   add: (a: number, b: number) => number;
 *   version: string;
 * }
 *
 * type MathWithId = NowId<MathFns>;
 * // {
 * //   add: (context: { $id: string, annotation?: string }, a: number, b: number) => number;
 * //   version: string;
 * // }
 * ```
 */
export type NowId<T> = {
    [K in keyof T]: T[K] extends (...args: any[]) => any ? WithNowId<T[K]> : T[K]
}
